'use client'
import { announce, cn, useControllableSignal, useSignals } from '@cascivo/core'
import { builtin, t } from '@cascivo/i18n'
import type { HTMLAttributes } from 'react'
import { CopyButton } from '../copy-button/copy-button'
import { IconButton } from '../icon-button/icon-button'
import styles from './message-actions.module.css'

export type MessageFeedback = 'good' | 'bad'

export interface MessageActionsProps extends HTMLAttributes<HTMLDivElement> {
  copyValue?: string
  feedback?: MessageFeedback | null
  /**
   * Initial rating when uncontrolled.
   *
   * @defaultValue `null`
   * @see the component manifest
   */
  defaultFeedback?: MessageFeedback | null
  onFeedbackChange?: (feedback: MessageFeedback | null) => void
  onRegenerate?: () => void
  labels?: {
    group?: string
    good?: string
    bad?: string
    regenerate?: string
    recorded?: string
  }
}

function Thumb({ down }: { down?: boolean }) {
  return (
    <svg
      viewBox="0 0 16 16"
      width="16"
      height="16"
      fill="none"
      className={down ? styles['down'] : undefined}
    >
      <path
        d="M5 7v6.5H3a1 1 0 0 1-1-1V8a1 1 0 0 1 1-1h2Zm0 0 2.6-4.6a1.2 1.2 0 0 1 2.2.8L9.4 6H13a1.3 1.3 0 0 1 1.3 1.5l-.8 4.8a1.5 1.5 0 0 1-1.5 1.2H5"
        stroke="currentColor"
        strokeWidth="1.3"
        strokeLinejoin="round"
      />
    </svg>
  )
}

export function MessageActions({
  copyValue,
  feedback,
  defaultFeedback = null,
  onFeedbackChange,
  onRegenerate,
  labels,
  className,
  ...props
}: MessageActionsProps) {
  useSignals()
  const [current, setCurrent] = useControllableSignal<MessageFeedback | null>({
    ...(feedback !== undefined && { value: feedback }),
    defaultValue: defaultFeedback,
    ...(onFeedbackChange && { onChange: onFeedbackChange }),
  })
  const recorded = labels?.recorded ?? t(builtin.messageActions.recorded)

  // Pressing the active rating again clears it, like any toggle button.
  const rate = (value: MessageFeedback) => {
    const next = current.value === value ? null : value
    setCurrent(next)
    if (next) announce(recorded)
  }

  return (
    <div
      role="group"
      aria-label={labels?.group ?? t(builtin.messageActions.group)}
      className={cn(styles['actions'], className as string | undefined)}
      {...props}
    >
      {copyValue !== undefined && <CopyButton value={copyValue} size="sm" />}
      {onFeedbackChange !== undefined || feedback !== undefined ? (
        <>
          <IconButton
            size="sm"
            ariaLabel={labels?.good ?? t(builtin.messageActions.good)}
            aria-pressed={current.value === 'good'}
            data-active={current.value === 'good' || undefined}
            className={styles['rate']}
            icon={<Thumb />}
            onClick={() => rate('good')}
          />
          <IconButton
            size="sm"
            ariaLabel={labels?.bad ?? t(builtin.messageActions.bad)}
            aria-pressed={current.value === 'bad'}
            data-active={current.value === 'bad' || undefined}
            className={styles['rate']}
            icon={<Thumb down />}
            onClick={() => rate('bad')}
          />
        </>
      ) : null}
      {onRegenerate && (
        <IconButton
          size="sm"
          ariaLabel={labels?.regenerate ?? t(builtin.messageActions.regenerate)}
          icon={
            <svg viewBox="0 0 16 16" width="16" height="16" fill="none">
              <path
                d="M13 8a5 5 0 1 1-1.5-3.6M13 2.5v2.5h-2.5"
                stroke="currentColor"
                strokeWidth="1.4"
                strokeLinecap="round"
                strokeLinejoin="round"
              />
            </svg>
          }
          onClick={onRegenerate}
        />
      )}
    </div>
  )
}

@layer cascivo.component {
  .actions {
    display: inline-flex;
    flex-wrap: wrap;
    align-items: center;
    gap: var(--cascivo-space-1);
    color: var(--cascivo-color-text-muted);
  }

  /* A vertical mirror, not a rotation: the glyph is drawn once, and nothing here turns. */
  .down {
    scale: 1 -1;
  }

  .rate {
    &[data-active] {
      color: var(--cascivo-color-ai);
      background-color: var(--cascivo-color-ai-subtle);
    }
  }
}

@media (forced-colors: active) {
  .rate[data-active] {
    outline: 2px solid Highlight;
  }
}

import type { ComponentMeta } from '@cascivo/core'

export const meta: ComponentMeta = {
  name: 'MessageActions',
  description:
    'The action row under an AI reply — copy, good / bad feedback as toggle buttons, and regenerate',
  category: 'inputs',
  clientJs: 'required',
  states: [],
  variants: [],
  sizes: [],
  props: [
    {
      name: 'copyValue',
      description: 'The text the Copy button copies. Omit to hide Copy.',
      type: 'string',
      required: false,
    },
    {
      name: 'feedback',
      description:
        'Controlled rating: `good`, `bad` or `null`. Pressing the active rating again clears it.',
      type: "'good' | 'bad' | null",
      required: false,
    },
    {
      name: 'defaultFeedback',
      description: 'Initial rating when uncontrolled.',
      type: "'good' | 'bad' | null",
      required: false,
      default: 'null',
    },
    {
      name: 'onFeedbackChange',
      description:
        'Called with the new rating (or `null` when cleared). The rating buttons render when this or `feedback` is set; a rating also announces "Thanks for your feedback".',
      type: "(feedback: 'good' | 'bad' | null) => void",
      required: false,
    },
    {
      name: 'onRegenerate',
      description: 'Called by the Regenerate button. Omit to hide it.',
      type: '() => void',
      required: false,
    },
    {
      name: 'labels',
      description: 'Overrides for the component’s user-visible strings (i18n).',
      type: '{ group?: string; good?: string; bad?: string; regenerate?: string; recorded?: string }',
      required: false,
    },
  ],
  tokens: ['--cascivo-color-text-muted', '--cascivo-color-ai', '--cascivo-color-ai-subtle'],
  accessibility: {
    role: 'group',
    wcag: '2.2-AA',
    keyboard: ['Tab', 'Enter', 'Space'],
    forcedColors: true,
  },
  examples: [
    {
      title: 'Copy, rate and regenerate',
      code: '<MessageActions copyValue="Refunds are available for 30 days." onFeedbackChange={() => {}} onRegenerate={() => {}} />',
    },
    { title: 'Copy only', code: '<MessageActions copyValue="Hello" />' },
  ],
  dependencies: ['@cascivo/core', '@cascivo/i18n'],
  registryDependencies: ['copy-button', 'icon-button'],
  tags: ['ai', 'chat', 'feedback', 'copy', 'regenerate', 'thumbs', 'actions'],
  intent: {
    whenToUse: [
      'Under each assistant message: copy the reply, rate it, or ask for another attempt',
    ],
    whenNotToUse: [
      'Stopping a response that is still generating — use AiStatus with onStop',
      'Actions on a non-AI item — use ButtonGroup or a Menu',
    ],
    antiPatterns: [
      {
        bad: 'Swapping the rating button’s label to "Good response recorded"',
        good: 'Keep a stable name and expose the choice with aria-pressed; the component announces the confirmation once',
        why: 'A name that changes on press reads as a different control; aria-pressed is how toggle buttons report state',
      },
    ],
    related: [
      {
        name: 'CopyButton',
        relationship: 'contains',
        reason: 'Copy is a CopyButton',
      },
      {
        name: 'AiStatus',
        relationship: 'pairs-with',
        reason:
          'AiStatus covers the in-progress phase; MessageActions appears once the reply is complete',
      },
    ],
    a11yRationale:
      'A named group of real buttons. Good and Bad are toggle buttons (aria-pressed), so the chosen rating is exposed as state rather than by a changing label, and choosing one announces "Thanks for your feedback" once through the shared announce() region. Icon buttons carry accessible names and meet the coarse-pointer target size',
    flexibility: [
      {
        area: 'which actions',
        level: 'flexible',
        note: 'Each action renders only when its prop is set',
      },
      {
        area: 'rating semantics',
        level: 'strict',
        note: 'Two-state good / bad toggles; do not repurpose them for other choices',
      },
    ],
  },
}
